def sortColors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

class MyDynamicArray:
    def __init__(self):
        self.size = 0
        self.capacity = 1
        self.data = [None] * self.capacity

    def add(self, val):
        if self.size == self.capacity:
            self._resize()    # Handle resizing
        self.data[self.size] = val
        self.size += 1

    def _resize(self):
        old_data = self.data
        self.capacity *= 2
        self.data = [None] * self.capacity
        for i in range(len(old_data)):
            self.data[i] = old_data[i]

    def get(self, index):
        return self.data[index] if index < self.size else None

